{"l":8480,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Freya spent her pocket money on seeds and spent every evening watering them. By August, the family hardly needed to buy vegetables.' Hvad viser teksten om Freya?","o":["Hun er tålmodig og flittig","Hun er doven og glemsom","Hun kan ikke lide grøntsager","Hun købte mange grøntsager"],"a":"Hun er tålmodig og flittig","r":"Hun vandede hver aften i månedsvis, og familien fik grøntsager nok. Det kræver tålmodighed og flid."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'grundigt' på engelsk i 'Read the contract ___ before signing'?","o":["roughly","thoroughly","briefly","loudly"],"a":"thoroughly","r":"'Thoroughly' betyder grundigt."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overvældende' på engelsk i 'an ___ majority'?","o":["overlapping","increasing","overwhelming","outstanding"],"a":"overwhelming","r":"'Overwhelming' = overvældende."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ulempe' på engelsk?","o":["feedback","backdrop","payback","drawback"],"a":"drawback","r":"'Drawback' betyder en ulempe."},
{"l":8520,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'jovial' i 'a jovial host'?","o":["cheerful","nervous","strict","wealthy"],"a":"cheerful","r":"'Jovial' betyder munter og hyggelig, altså 'cheerful'."},
{"l":8530,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'resolute' i 'a resolute leader'?","o":["nervous","determined","popular","elderly"],"a":"determined","r":"'Resolute' betyder beslutsom og målrettet, altså 'determined'."},
{"l":8550,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The school canteen has proudly announced its new healthy menu, which, as far as anyone can tell, consists of the old menu with a side salad.' Hvad mener skribenten?","o":["At den nye menu er meget sundere","At kantinen er blevet lukket","At menuen stort set er den samme","At salaten er det eneste problem"],"a":"At menuen stort set er den samme","r":"Skribenten er ironisk: den 'nye' menu er bare den gamle med en salat ved siden af."},
{"l":8570,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ any further information, please contact the school office.'","o":["You should need","Should need you","If you needing","Should you need"],"a":"Should you need","r":"'Should you need' er en formel, inverteret betingelse (= If you need). De andre former er grammatisk forkerte."},
{"l":8590,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'by and large' i 'By and large, the school trip was a success.'?","o":["stort set","til sidst","overraskende nok","desværre"],"a":"stort set","r":"'By and large' betyder i det store og hele eller stort set."},
{"l":8610,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man høfligt beder nogen om at vente et øjeblik, mens man finder noget?","o":["Carry with me a moment.","Bear with me a moment.","Wait on me a moment.","Hold me a moment."],"a":"Bear with me a moment.","r":"'Bear with me' er en høflig måde at bede om lidt tålmodighed på. 'Wait on me' betyder at betjene mig."},
{"l":8640,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'bewildered' i 'a bewildered tourist'?","o":["delighted","wealthy","confused","lonely"],"a":"confused","r":"'Bewildered' betyder forvirret og rådvild, altså 'confused'."},
{"l":8660,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'conceal' i 'conceal the truth'?","o":["ignore","bend","accept","reveal"],"a":"reveal","r":"'Conceal' betyder at skjule, så det modsatte er 'reveal' (afsløre)."},
{"l":8690,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'sparse' i 'sparse vegetation'?","o":["dense","dry","green","tall"],"a":"dense","r":"'Sparse' betyder spredt eller tynd, så det modsatte er 'dense' (tæt)."},
{"l":8710,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ella insists she is not a morning person, yet she is always the first to arrive at swimming practice at six.' Hvad er det overraskende ved Ella?","o":["At hun ikke kan lide at svømme længere","At hun opfører sig modsat det, hun siger","At hun ofte kommer for sent til træning","At hun hellere vil træne om aftenen"],"a":"At hun opfører sig modsat det, hun siger","r":"'Yet' viser en modsætning: hun siger, hun ikke er et morgenmenneske, men hun kommer først klokken seks."},
{"l":8730,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Lucas said he would think about joining the chess club, which, from Lucas, usually means no.' Hvad antyder teksten?","o":["At Lucas elsker at spille skak","At Lucas skal tænke i lang tid","At Lucas nok ikke melder sig ind","At Lucas allerede er medlem"],"a":"At Lucas nok ikke melder sig ind","r":"'Which, from Lucas, usually means no' viser, at hans 'I will think about it' plejer at være et høfligt nej."},
{"l":8760,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'utrættelige' på engelsk i 'Thanks to her ___ efforts, the library finally got new computers.'?","o":["careless","harmless","priceless","tireless"],"a":"tireless","r":"'Tireless' betyder utrættelig. 'Priceless' betyder uvurderlig, og 'careless' betyder skødesløs."},
{"l":8800,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Supposing you ___ a million kroner, what would you do with it?'","o":["found","will find","find","have found"],"a":"found","r":"'Supposing' fungerer som 'if' i en type 2-betingelse, så man bruger datid ('found') sammen med 'would'."},
{"l":8820,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'My brother speaks three languages fluently, and so ___ my cousin.'","o":["is","does","can","has"],"a":"does","r":"Efter 'and so' gentages hjælpeverbet; 'speaks' er nutid uden hjælpeverbum, så man bruger 'does': 'so does my cousin'."},
{"l":8850,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The results appear to suggest that the new medicine may reduce symptoms in some patients, although further research is needed.' Hvor sikre er forskerne på resultatet?","o":["Helt sikre på, at medicinen virker","Uinteresserede i resultaterne","Forsigtige og ikke helt sikre","Sikre på, at medicinen er farlig"],"a":"Forsigtige og ikke helt sikre","r":"Ord som 'appear to suggest', 'may' og 'some' er forsigtige formuleringer (hedging), og der kræves mere forskning."},
{"l":8880,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'åbenlys' på engelsk i 'It was a ___ attempt to copy someone else's homework.'?","o":["blank","bland","brutal","blatant"],"a":"blatant","r":"'Blatant' betyder åbenlys og skamløs. 'Bland' betyder smagløs, og 'blank' betyder tom."},
{"l":8910,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'It's not the price ___ worries me, it's the quality.'","o":["that","what","who","how"],"a":"that","r":"Kløvet sætning: 'It's not X that ...' fremhæver, hvad der bekymrer. 'What' kan ikke bruges i denne konstruktion."},
{"l":8950,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'cluttered' i 'a cluttered desk'?","o":["busy","tidy","wooden","heavy"],"a":"tidy","r":"'Cluttered' betyder rodet og fyldt med ting, så det modsatte er 'tidy' (ryddelig)."},
{"l":8990,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'It could be argued that homework in the lower grades does more harm than good, though the evidence is far from conclusive.' Hvordan fremlægger skribenten sit synspunkt?","o":["Skråsikkert og uden tvivl","Vredt og meget personligt","Forsigtigt og med forbehold","Humoristisk og let"],"a":"Forsigtigt og med forbehold","r":"'It could be argued' og 'far from conclusive' er forsigtige formuleringer, der tager forbehold."},
{"l":8996,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'yderst omhyggeligt' på engelsk i 'The plan was ___ prepared'?","o":["miraculously","ridiculously","mysteriously","meticulously"],"a":"meticulously","r":"'Meticulously' = meget omhyggeligt."},
{"l":9008,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'anonym' på engelsk?","o":["anonymous","unanimous","autonomous","synonymous"],"a":"anonymous","r":"'Anonymous' = anonym."},
{"l":9019,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'kynisk' på engelsk?","o":["clinical","cynical","cyclical","typical"],"a":"cynical","r":"'Cynical' = kynisk."},
{"l":9020,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'What happened ___ that the ferry left without us.'","o":["had","did","was","were"],"a":"was","r":"I den kløvede sætning 'What happened was that ...' er 'What happened' ental-subjekt for 'was'."},
{"l":9031,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'velvillig' på engelsk?","o":["malevolent","belligerent","ambivalent","benevolent"],"a":"benevolent","r":"'Benevolent' = velvillig."},
{"l":9043,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omstridt' på engelsk?","o":["contentious","conscientious","contagious","continuous"],"a":"contentious","r":"'Contentious' = kontroversiel."},
{"l":9050,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Nowhere ___ more beautiful beaches than on this island.'","o":["find you","will you find","you will find","you find"],"a":"will you find","r":"Negative stedsadverbier som 'Nowhere' først i sætningen kræver inversion: 'will you find'."},
{"l":9054,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'kontroversiel / omstridt' på engelsk?","o":["conversational","conventional","controversial","confidential"],"a":"controversial","r":"'Controversial' = omstridt."},
{"l":9064,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forsigtig / foreløbig' på engelsk?","o":["attentive","tenacious","talkative","tentative"],"a":"tentative","r":"'Tentative' betyder foreløbig eller forsigtig."},
{"l":9076,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sejlivet / udholdende' på engelsk?","o":["tenacious","tentative","spacious","gracious"],"a":"tenacious","r":"'Tenacious' betyder vedholdende."},
{"l":9080,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'I'd sooner ___ at home than go to that crowded concert.'","o":["staying","stay","to stay","stayed"],"a":"stay","r":"'Would sooner' betyder det samme som 'would rather' og efterfølges af grundformen uden 'to'."},
{"l":9089,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ligeglad' på engelsk?","o":["different","indignant","indifferent","independent"],"a":"indifferent","r":"'Indifferent' = ligeglad."},
{"l":9100,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'To say that the first rehearsal did not go entirely to plan would be something of an understatement.' Hvordan gik den første prøve?","o":["Næsten perfekt","Helt efter planen","Lidt bedre end ventet","Rigtig dårligt"],"a":"Rigtig dårligt","r":"'Something of an understatement' betyder, at 'not entirely to plan' er en stor underdrivelse; det gik meget dårligt."},
{"l":9101,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overflødig / afskediget' på engelsk?","o":["redundant","abundant","reluctant","recurrent"],"a":"redundant","r":"'Redundant' betyder overflødig. 'Made redundant' betyder fyret pga. nedskæringer."},
{"l":9112,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'nidkær' på engelsk?","o":["jealous","zealous","callous","jovial"],"a":"zealous","r":"'Zealous' = nidkær, ivrig."},
{"l":9124,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'modstandsdygtig' på engelsk?","o":["resident","relevant","resilient","reticent"],"a":"resilient","r":"'Resilient' betyder, at man hurtigt kommer sig efter modgang."},
{"l":9136,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forværres' på engelsk?","o":["determine","decorate","deliberate","deteriorate"],"a":"deteriorate","r":"'Deteriorate' betyder at blive værre."},
{"l":9140,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'reprimanded' i 'The referee reprimanded the player for wasting time.'?","o":["irettesatte","roste","udviste","trøstede"],"a":"irettesatte","r":"'Reprimand' betyder at irettesætte nogen. At blive udvist hedder 'be sent off'."},
{"l":9147,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'lindre' på engelsk?","o":["alienate","alleviate","allocate","abbreviate"],"a":"alleviate","r":"'Alleviate' betyder at lindre, fx smerte eller problemer."},
{"l":9159,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'besværlig / slidsom' på engelsk?","o":["ardent","dubious","arduous","hazardous"],"a":"arduous","r":"'Arduous' = krævende."},
{"l":9160,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'By the time the rescue team reached the summit, the climbers had already begun their descent. The helicopter, it turned out, had not been needed after all.' Hvad kan man udlede af teksten?","o":["At helikopteren styrtede ned","At redningsholdet aldrig kom frem","At klatrerne var kommet til skade","At klatrerne klarede sig selv ned"],"a":"At klatrerne klarede sig selv ned","r":"Klatrerne var allerede på vej ned, og helikopteren var ikke nødvendig, så de klarede sig uden hjælp."},
{"l":9170,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'underminere / svække' på engelsk?","o":["undermine","underline","undertake","undergo"],"a":"undermine","r":"'Undermine' betyder at svække noget gradvist."},
{"l":9180,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'She ___ have seen me at the party, because I wasn't there.'","o":["mustn't","can't","shouldn't","needn't"],"a":"can't","r":"'Can't have' + kort tillægsform udtrykker, at noget er umuligt i fortiden. 'Mustn't have' bruges ikke om sikre slutninger på britisk engelsk."},
{"l":9182,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'undervurdere' på engelsk?","o":["overestimate","underperform","underestimate","investigate"],"a":"underestimate","r":"'Underestimate' betyder at undervurdere."},
{"l":9194,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'håndgribelig' på engelsk?","o":["tenable","tolerable","terrible","tangible"],"a":"tangible","r":"'Tangible' = konkret, håndgribelig."},
{"l":9205,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sandsynlig / troværdig' på engelsk?","o":["plausible","passable","palpable","laudable"],"a":"plausible","r":"'Plausible' betyder, at noget lyder troværdigt."},
{"l":9210,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'inquisitive' i 'an inquisitive child'?","o":["polite","curious","anxious","clumsy"],"a":"curious","r":"'Inquisitive' betyder videbegærlig og nysgerrig, altså 'curious'."},
{"l":9223,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'udtrykkelig / tydelig' på engelsk?","o":["implicit","illicit","explicit","exquisite"],"a":"explicit","r":"'Explicit' betyder klart udtrykt."},
{"l":9230,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Should the weather ___, the picnic will be moved indoors.'","o":["worsens","worsened","to worsen","worsen"],"a":"worsen","r":"'Should + subjekt + grundform' er en inverteret betingelse (= If the weather worsens), så verbet står i grundform."},
{"l":9240,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'rigelig' på engelsk?","o":["abundant","redundant","abrupt","ardent"],"a":"abundant","r":"'Abundant' betyder, at der er rigeligt af noget."},
{"l":9252,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'enighed' på engelsk?","o":["census","consensus","conscience","consequence"],"a":"consensus","r":"'Consensus' = bred enighed."},
{"l":9259,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'afbøde / mildne' på engelsk?","o":["litigate","migrate","mitigate","instigate"],"a":"mitigate","r":"'Mitigate' betyder at gøre noget mindre alvorligt."},
{"l":9263,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forsigtigt / foreløbigt' på engelsk?","o":["attentively","tenaciously","repetitively","tentatively"],"a":"tentatively","r":"'Tentatively' = forsigtigt."},
{"l":9275,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'incitament / tilskyndelse' på engelsk?","o":["incentive","initiative","invective","incidence"],"a":"incentive","r":"'Incentive' = noget, der motiverer."},
{"l":9287,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overse / have udsigt over' på engelsk?","o":["oversee","overlook","overtake","overdo"],"a":"overlook","r":"'Overlook' = overse eller have udsigt over."},
{"l":9298,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'afsløre som falsk' på engelsk?","o":["debug","debate","debunk","devour"],"a":"debunk","r":"'Debunk' = afsløre en myte."},
{"l":9300,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'tøven' på engelsk i 'After a moment of ___, she agreed to give the speech.'?","o":["hostility","humiliation","hospitality","hesitation"],"a":"hesitation","r":"'Hesitation' betyder tøven. 'Hostility' er fjendtlighed, og 'hospitality' er gæstfrihed."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omfattende' på engelsk?","o":["comprehensive","comprehensible","apprehensive","competitive"],"a":"comprehensive","r":"'Comprehensive' betyder omfattende. Forståelig hedder 'comprehensible'."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Although Maya claims she hardly studied, her notebooks are full of colour-coded summaries and practice essays.' Hvad antyder teksten om Maya?","o":["At hun ikke har lavet noget","At hun har arbejdet mere, end hun siger","At hun er dårlig til at tegne","At hun har lånt en andens noter"],"a":"At hun har arbejdet mere, end hun siger","r":"'Although' viser en modsætning: hun siger, hun næsten ikke har læst, men noterne viser det modsatte."},
{"l":9330,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Little ___ that her quiet classmate would become a famous author.'","o":["she knew","knew she","did she know","she did know"],"a":"did she know","r":"'Little' først i sætningen med betydningen 'slet ikke' kræver inversion med 'did': 'Little did she know'."},
{"l":9333,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'svinde ind' på engelsk?","o":["swindle","dawdle","kindle","dwindle"],"a":"dwindle","r":"'Dwindle' = blive gradvist mindre."},
{"l":9345,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'mandat' på engelsk i 'The government has a ___ to act'?","o":["mandate","mantra","menace","motive"],"a":"mandate","r":"'Mandate' = bemyndigelse."},
{"l":9356,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ikke desto mindre' på engelsk i 'It was raining. ___, we went out'?","o":["furthermore","nevertheless","therefore","meanwhile"],"a":"nevertheless","r":"'Nevertheless' betyder ikke desto mindre."},
{"l":9360,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The comment from the teacher ___ a heated debate in the classroom.'","o":["sparkled","spotted","sparked","sparred"],"a":"sparked","r":"'Spark a debate' betyder at sætte gang i en diskussion. 'Sparkled' betyder funklede."},
{"l":9370,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'mundane' i 'mundane tasks'?","o":["practical","domestic","repetitive","extraordinary"],"a":"extraordinary","r":"'Mundane' betyder hverdagsagtig og kedelig, så det modsatte er 'extraordinary' (usædvanlig)."},
{"l":9390,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Few people realise that the humble potato, now a staple across Europe, was once regarded with deep suspicion.' Hvad fortæller teksten om kartoflen?","o":["At man engang var mistroisk over for den","At den altid har været meget populær","At den oprindeligt kommer fra Danmark","At den i dag sjældent spises i Europa"],"a":"At man engang var mistroisk over for den","r":"'Was once regarded with deep suspicion' betyder, at folk engang var meget mistroiske over for kartoflen."},
{"l":9400,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil bede om lidt betænkningstid til i morgen, før man svarer?","o":["Let me take it easy.","Let me sleep on it.","Let me give it up.","Let me get over it."],"a":"Let me sleep on it.","r":"'Let me sleep on it' betyder, at man vil tænke over det til næste dag. 'Get over it' betyder at komme sig over noget."},
{"l":9414,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bagklogskab' på engelsk?","o":["foresight","insight","hindsight","eyesight"],"a":"hindsight","r":"'In hindsight' = set i bakspejlet."},
{"l":9440,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'eclectic' i 'Her taste in music is very eclectic.'?","o":["gammeldags","snæver","støjende","alsidig"],"a":"alsidig","r":"'Eclectic' betyder alsidig og sammensat af mange forskellige stilarter."},
{"l":9470,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'fritaget' på engelsk i 'Pupils with a doctor's note are ___ from swimming lessons.'?","o":["exempt","expelled","exposed","extended"],"a":"exempt","r":"'Exempt from' betyder fritaget for. 'Expelled' betyder bortvist, hvilket er noget helt andet."},
{"l":9500,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'So quickly ___ that nobody noticed her leave.'","o":["she moved","did she move","moved she","she did move"],"a":"did she move","r":"Når 'So + biord' står først med 'that', bruges inversion med 'did': 'So quickly did she move'."},
{"l":9530,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'No sooner had the match started ___ it began to pour with rain.'","o":["when","then","than","that"],"a":"than","r":"Det faste mønster er 'No sooner had ... than ...'. 'When' bruges i stedet med 'Hardly' eller 'Scarcely'."},
{"l":9560,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'overdreven' på engelsk i 'Spending ___ amounts of time online can affect your sleep.'?","o":["expressive","exclusive","exhaustive","excessive"],"a":"excessive","r":"'Excessive' betyder overdreven. 'Exclusive' betyder eksklusiv, og 'exhaustive' betyder udtømmende."},
{"l":9580,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'covert' i 'a covert glance'?","o":["overt","nervous","quick","friendly"],"a":"overt","r":"'Covert' betyder skjult eller hemmelig, så det modsatte er 'overt' (åbenlys)."},
{"l":9610,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Few would dispute that the bridge is an engineering marvel; whether it was worth three times its original budget is another matter.' Hvad mener skribenten?","o":["Broen er grim, men den var heldigvis billig","Broen er imponerende, men prisen kan diskuteres","Broen blev bygget hurtigere end planlagt","Ingen mener, at broen er særlig imponerende"],"a":"Broen er imponerende, men prisen kan diskuteres","r":"'Few would dispute' betyder, at næsten alle er enige om, at broen er imponerende, mens 'another matter' sår tvivl om prisen."},
{"l":9640,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'tilbageholdende' på engelsk i 'She was ___ about her plans, so nobody knew where she was going.'?","o":["redundant","repetitive","reticent","resentful"],"a":"reticent","r":"'Reticent' betyder tilbageholdende og fåmælt om sig selv. 'Resentful' betyder bitter, og 'redundant' betyder overflødig."},
{"l":9660,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The school choir ___ perform at the royal palace next month.'","o":["is about","is due","is used","is to"],"a":"is to","r":"'Be to + grundform' bruges formelt om noget, der er planlagt. 'Is about' og 'is due' kræver 'to' efter sig."},
{"l":9690,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'galvanised' i 'The flood galvanised the villagers into building a new dam.'?","o":["ansporede","skræmte","forhindrede","skuffede"],"a":"ansporede","r":"'Galvanise someone into' betyder at anspore nogen til at handle; oversvømmelsen fik landsbyen til at bygge en dæmning."},
{"l":9710,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'ostracised' i 'In ancient Athens, unpopular citizens could be ostracised for ten years.'?","o":["belønnet","forvist","valgt","fængslet"],"a":"forvist","r":"'Ostracise' betyder at udstøde eller forvise; i oldtidens Athen kunne man blive sendt væk fra byen i ti år."},
{"l":9730,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man foreslår at stoppe en diskussion og acceptere, at man ikke er enige?","o":["Let's disagree together.","Let's be agree about it.","Let's agree to disagree.","Let's agree with disagreeing."],"a":"Let's agree to disagree.","r":"'Let's agree to disagree' er det faste udtryk for at acceptere, at man har forskellige meninger."},
{"l":9760,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'nonchalant' i 'He looked nonchalant, even though the exam started in five minutes.'?","o":["rystet","forvirret","forsinket","ubekymret"],"a":"ubekymret","r":"'Nonchalant' betyder ubekymret og afslappet, selv om situationen er alvorlig."},
{"l":9790,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Such ___ the demand for tickets that the concert sold out in minutes.'","o":["was","did","had","were"],"a":"was","r":"'Such was ... that ...' er en inverteret, fremhævende konstruktion; 'the demand' er ental, så verbet er 'was'."},
{"l":9810,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Although the team lost the final, the coach described the season as the most rewarding of her career.' Hvad kan man udlede om træneren?","o":["At hun var meget skuffet over sæsonen","At hun lægger vægt på mere end sejre","At holdet vandt finalen til sidst","At hun stopper efter denne sæson"],"a":"At hun lægger vægt på mere end sejre","r":"'Although' viser, at hun er glad for sæsonen trods nederlaget; hun værdsætter altså andet end at vinde."},
{"l":9840,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil sige, at to ting er helt forskellige og ikke kan sammenlignes?","o":["It's like comparing cats and mice.","They are like two drops of water.","It's like comparing apples and oranges.","It's like apples and pears together."],"a":"It's like comparing apples and oranges.","r":"'Comparing apples and oranges' betyder at sammenligne ting, der ikke kan sammenlignes. 'Like two drops of water' ville betyde, at de er ens."},
{"l":9870,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Our class representative, never one to miss an opportunity to speak, gave a forty-minute answer to a yes-or-no question.' Hvad antyder teksten om klasserepræsentanten?","o":["At personen er meget genert","At personen svarede kort og præcist","At personen ikke forstod spørgsmålet","At personen elsker at tale længe"],"a":"At personen elsker at tale længe","r":"'Never one to miss an opportunity to speak' og et svar på 40 minutter til et ja-nej-spørgsmål viser ironisk, at personen taler meget."},
{"l":9890,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'a rule of thumb' i 'As a rule of thumb, you should drink water before you feel thirsty.'?","o":["en tommelfingerregel","en streng lov","en sjælden undtagelse","en gammel overtro"],"a":"en tommelfingerregel","r":"'A rule of thumb' er en tommelfingerregel, altså en praktisk hovedregel."},
{"l":9930,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'fragile' i 'a fragile vase'?","o":["valuable","sturdy","empty","ancient"],"a":"sturdy","r":"'Fragile' betyder skrøbelig, så det modsatte er 'sturdy' (robust, solid)."},
{"l":9960,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Our neighbour describes his garden as low-maintenance, which in practice means he has paved over most of it.' Hvilken tone har skribenten?","o":["Dybt beundrende","Helt neutral","Let spydig","Meget vred"],"a":"Let spydig","r":"'Which in practice means' afslører med et lille stik, at haven er nem at passe, fordi den mest er belagt med fliser."},
{"l":9980,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'In theory, the new homework platform saves teachers time. In practice, it has created an entirely new job: explaining how the platform works.' Hvad er skribentens pointe?","o":["At platformen sparer meget tid","At eleverne elsker platformen","At lærerne ikke vil bruge den","At platformen skaber mere arbejde"],"a":"At platformen skaber mere arbejde","r":"Kontrasten 'In theory ... In practice' viser ironisk, at platformen giver lærerne ekstra arbejde i stedet for at spare tid."},
{"l":9995,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'trods / uanset' på engelsk i '___ the cost, the project went ahead'?","o":["notwithstanding","in addition to","on behalf of","with regard to"],"a":"notwithstanding","r":"'Notwithstanding' = på trods af."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'utilsigtet' på engelsk?","o":["indefinitely","inadvertently","intermittently","independently"],"a":"inadvertently","r":"'Inadvertently' = uden at mene det."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
